/**
 * The revenue model, as arithmetic rather than as a claim in a paragraph.
 *
 * The DICT screening committee's one business-model objection was that "the
 * relatively low subscription prices mean the business will need a large number
 * of paying users to generate sufficient revenue", and asked for "a revenue
 * projection based on realistic adoption rates". A projection nobody can
 * recompute is a guess with a table around it, so the numbers in
 * `REVENUE_PROJECTION.md` are generated by this file and can be regenerated by
 * anyone with the repository.
 *
 * Run it with:   node tools/revenue-model.mjs
 * It writes:     revenue-projection.csv   (the three scenarios, month by month)
 *                and prints the markdown tables pasted into the note.
 *
 * Every assumption is a named constant below with its basis in a comment. Two
 * rules are deliberate:
 *
 * 1. **Costs are held pessimistic, revenue is not held optimistic.** An
 *    infrastructure estimate that flatters the margin is the easiest way to lose
 *    a panel's trust on a number they can check.
 * 2. **Adoption is expressed as penetration of the stores actually onboarded**,
 *    never as a share of the 1.1 million microenterprises. Nobody credible
 *    captures a national market in 24 months, and a model that assumes it reads
 *    as arithmetic performance rather than a plan.
 */

import { writeFileSync } from 'node:fs'

// ---------------------------------------------------------------------------
// Pricing — the numbers the app itself ships (src/billing.ts)
// ---------------------------------------------------------------------------

const PRO_MONTHLY = 99 // ₱99/month
const PRO_ANNUAL = 999 // ₱999/year, ~2 months free
/** Share of paying stores that take the annual plan. Prepay is the norm here. */
const ANNUAL_SHARE = 0.3
/**
 * Effective monthly revenue per paying store, after the annual discount.
 * This is the number that matters: quoting ₱99 without it overstates the top
 * line by about 5% for a book that is entirely prepaid.
 */
const PRO_EFFECTIVE =
  (1 - ANNUAL_SHARE) * PRO_MONTHLY + ANNUAL_SHARE * (PRO_ANNUAL / 12)

/** Institutional licences are sold per covered store per year, in bulk. */
const INSTITUTIONAL_PER_STORE_YEAR = 120

// ---------------------------------------------------------------------------
// Variable costs
// ---------------------------------------------------------------------------

/**
 * PayMongo's published GCash rate: 2.23% + VAT (12%) = 2.4976%.
 * The e-wallet rate, not the card rate (3.125% + ₱13.39), because ₱99 by card is
 * uneconomic at this size — one reason the pilot has to test payment mix too.
 */
const PAYMENT_FEE_RATE = 0.0223 * 1.12

/**
 * Supabase: free until the free tier runs out, then the $25/month Pro plan.
 * Free projects also pause after a week of inactivity and take no backups, so
 * Pro is the real production price, not an upsell.
 */
const USD_TO_PHP = 58
const SUPABASE_PRO_MONTHLY = 25 * USD_TO_PHP // ≈ ₱1,450
/** Encrypted backups supported by one Pro project's 8 GB database at ~2.5 MB/store/year. */
const STORES_PER_SUPABASE_PROJECT = 3000
/** The free tier's 500 MB holds roughly 150 stores' backups before the first invoice. */
const FREE_TIER_STORES = 150

/**
 * AI narration, held deliberately high.
 *
 * The concept note models metered voice at ~₱0.006/minute of audio, which does
 * not apply here: recognition runs on the owner's phone or in the browser. What
 * costs money is the *narration* call, metered at 300 questions a month per
 * subscriber. ₱0.25 per question is a placeholder set well above a small model's
 * real cost, precisely so the margin cannot be flattered by an unmeasured
 * assumption. The pilot replaces it with observed usage.
 */
const AI_COST_PER_QUESTION = 0.25
/** Share of paying stores that actually use the AI layer in a given month. */
const AI_USE_SHARE = 0.3
/** Questions per active user per month, against the 300-question cap. */
const AI_QUESTIONS_PER_MONTH = 100

// ---------------------------------------------------------------------------
// Adoption — three scenarios
// ---------------------------------------------------------------------------

/**
 * Active stores (free + paying) at each review point. The first twelve months
 * are the pilot and its neighbourhood; the second year is regional replication
 * through institutional partners. The optimistic case is roughly 0.3% of the
 * country's 1.13 million microenterprises at the end — ambitious, and still not
 * a market-share claim.
 */
const SCENARIOS = [
  {
    id: 'conservative',
    label: 'Conservative',
    stores: [0, 30, 30, 60, 120, 200, 300, 420, 560, 700, 850, 1000, 1200, 1400, 1600, 1800, 2000, 2200, 2400, 2600, 2800, 3000, 3200, 3400],
    proShare: 0.04,
    institutional: [0, 0, 0, 0, 0, 0, 0, 0, 0, 150, 150, 300, 300, 450, 450, 600, 600, 750, 750, 900, 900, 1050, 1050, 1200],
  },
  {
    id: 'base',
    label: 'Base',
    stores: [0, 30, 45, 90, 180, 300, 450, 650, 900, 1200, 1500, 1800, 2200, 2600, 3000, 3500, 4000, 4500, 5000, 5500, 6000, 6600, 7200, 7800],
    proShare: 0.08,
    institutional: [0, 0, 0, 0, 0, 0, 0, 0, 150, 300, 300, 600, 600, 900, 900, 1500, 1500, 2100, 2400, 2700, 3000, 3300, 3600, 3900],
  },
  {
    id: 'optimistic',
    label: 'Optimistic',
    stores: [0, 30, 60, 140, 300, 500, 750, 1100, 1500, 2000, 2500, 3000, 3600, 4200, 4800, 5500, 6200, 7000, 8000, 8800, 9600, 10500, 11500, 12500],
    proShare: 0.14,
    institutional: [0, 0, 0, 0, 0, 0, 0, 150, 300, 600, 600, 900, 1200, 1500, 1800, 2400, 2700, 3300, 3900, 4500, 5100, 5700, 6300, 6900],
  },
]

const FIRST_MONTH = { year: 2027, month: 1 } // January 2027, after the pilot starts in February
/** 24 months: M1 is the eve of the pilot, M24 is the end of year two. */
const MONTHS = 24
for (const scenario of SCENARIOS) {
  if (scenario.stores.length !== MONTHS || scenario.institutional.length !== MONTHS) {
    throw new Error(`${scenario.id}: every series must be ${MONTHS} months long`)
  }
}

function monthLabel(index) {
  const total = FIRST_MONTH.month - 1 + index
  const year = FIRST_MONTH.year + Math.floor(total / 12)
  const month = (total % 12) + 1
  return `${year}-${String(month).padStart(2, '0')}`
}

/** One month of the model, as a row of figures rather than a summary sentence. */
function project(scenario, index) {
  const stores = scenario.stores[index]
  const proStores = Math.round(stores * scenario.proShare)
  const licensedStores = scenario.institutional[index]

  const subscription = proStores * PRO_EFFECTIVE
  const institutional = (licensedStores * INSTITUTIONAL_PER_STORE_YEAR) / 12
  const revenue = subscription + institutional

  const paymentFees = revenue * PAYMENT_FEE_RATE
  const infrastructure =
    proStores <= FREE_TIER_STORES
      ? 0
      : Math.ceil(proStores / STORES_PER_SUPABASE_PROJECT) * SUPABASE_PRO_MONTHLY
  const aiCost = proStores * AI_USE_SHARE * AI_QUESTIONS_PER_MONTH * AI_COST_PER_QUESTION

  const costs = paymentFees + infrastructure + aiCost
  return {
    month: monthLabel(index),
    stores,
    proStores,
    licensedStores,
    revenue,
    subscription,
    institutional,
    paymentFees,
    infrastructure,
    aiCost,
    costs,
    contribution: revenue - costs,
    margin: revenue > 0 ? (revenue - costs) / revenue : 0,
  }
}

const pesos = (n) => Math.round(n * 100) / 100
const csv = (n) => pesos(n).toFixed(2)

const rowsByScenario = new Map(
  SCENARIOS.map((scenario) => [scenario.id, Array.from({ length: MONTHS }, (_, i) => project(scenario, i))]),
)

// ---------------------------------------------------------------------------
// The CSV: every month, every scenario, in a form a spreadsheet can open
// ---------------------------------------------------------------------------

const header = [
  'scenario',
  'month',
  'active_stores',
  'paying_stores',
  'institutional_stores',
  'revenue_php',
  'subscription_php',
  'institutional_php',
  'payment_fees_php',
  'infrastructure_php',
  'ai_costs_php',
  'contribution_php',
  'contribution_margin',
]

const csvLines = [header.join(',')]
for (const scenario of SCENARIOS) {
  for (const row of rowsByScenario.get(scenario.id)) {
    csvLines.push(
      [
        scenario.id,
        row.month,
        row.stores,
        row.proStores,
        row.licensedStores,
        csv(row.revenue),
        csv(row.subscription),
        csv(row.institutional),
        csv(row.paymentFees),
        csv(row.infrastructure),
        csv(row.aiCost),
        csv(row.contribution),
        row.margin.toFixed(4),
      ].join(','),
    )
  }
}
writeFileSync('revenue-projection.csv', csvLines.join('\n') + '\n', 'utf8')

// ---------------------------------------------------------------------------
// Markdown tables for the note
// ---------------------------------------------------------------------------

const money = (n) => `₱${Math.round(n).toLocaleString('en-PH')}`

function sumMonths(rows, from, to) {
  return rows.slice(from, to).reduce(
    (acc, row) => ({
      revenue: acc.revenue + row.revenue,
      subscription: acc.subscription + row.subscription,
      institutional: acc.institutional + row.institutional,
      costs: acc.costs + row.costs,
      contribution: acc.contribution + row.contribution,
    }),
    { revenue: 0, subscription: 0, institutional: 0, costs: 0, contribution: 0 },
  )
}

console.log('## Twelve-month summary (first year from pilot)\n')
console.log('| Scenario | Paying stores (end of M12) | Subscription revenue (M12) | Institutional revenue (M12) | Total revenue (M12) | Annual run-rate |')
console.log('| --- | --- | --- | --- | --- | --- |')
for (const scenario of SCENARIOS) {
  const rows = rowsByScenario.get(scenario.id)
  const m12 = rows[12]
  const year1 = sumMonths(rows, 0, 13)
  console.log(
    `| ${scenario.label} | ${m12.proStores} | ${money(m12.subscription)} | ${money(m12.institutional)} | ${money(m12.revenue)} | ${money(m12.revenue * 12)} |`,
  )
  void year1
}

console.log('\n## Second-year summary (M13–M24)\n')
console.log('| Scenario | Paying stores (end of M24) | Stores licensed by partners | Year-2 revenue | Year-2 cost | Year-2 contribution | Margin |')
console.log('| --- | --- | --- | --- | --- | --- | --- |')
for (const scenario of SCENARIOS) {
  const rows = rowsByScenario.get(scenario.id)
  const y2 = sumMonths(rows, 12, MONTHS)
  const last = rows[MONTHS - 1]
  console.log(
    `| ${scenario.label} | ${rows[rows.length - 1].proStores} | ${last.licensedStores} | ${money(y2.revenue)} | ${money(y2.costs)} | ${money(y2.contribution)} | ${(y2.revenue > 0 ? (y2.contribution / y2.revenue) * 100 : 0).toFixed(0)}% |`,
  )
}

console.log('\n## Unit economics per paying store, per month\n')
console.log('| Item | Value | Basis |')
console.log('| --- | --- | --- |')
console.log(`| Effective revenue | ₱${PRO_EFFECTIVE.toFixed(2)} | ${(ANNUAL_SHARE * 100).toFixed(0)}% annual prepay at ₱${PRO_ANNUAL} |`)
console.log(`| Payment fee | ₱${(PRO_EFFECTIVE * PAYMENT_FEE_RATE).toFixed(2)} | ${(PAYMENT_FEE_RATE * 100).toFixed(4)}% GCash + VAT |`)
console.log(
  `| AI narration | ₱${(AI_USE_SHARE * AI_QUESTIONS_PER_MONTH * AI_COST_PER_QUESTION).toFixed(2)} | ${(AI_USE_SHARE * 100).toFixed(0)}% using it, ${AI_QUESTIONS_PER_MONTH} questions at ₱${AI_COST_PER_QUESTION.toFixed(2)} (placeholder, deliberately high) |`,
)
console.log(
  `| Infrastructure | ₱${(SUPABASE_PRO_MONTHLY / STORES_PER_SUPABASE_PROJECT).toFixed(2)} | ₱${SUPABASE_PRO_MONTHLY.toFixed(0)}/month covers ~${STORES_PER_SUPABASE_PROJECT} stores |`,
)
const variableCost =
  PRO_EFFECTIVE * PAYMENT_FEE_RATE +
  AI_USE_SHARE * AI_QUESTIONS_PER_MONTH * AI_COST_PER_QUESTION +
  SUPABASE_PRO_MONTHLY / STORES_PER_SUPABASE_PROJECT
console.log(
  `| **Contribution** | **₱${(PRO_EFFECTIVE - variableCost).toFixed(2)}** | **${(((PRO_EFFECTIVE - variableCost) / PRO_EFFECTIVE) * 100).toFixed(0)}% gross margin** |`,
)

console.log('\n## Break-even on infrastructure\n')
console.log(`- Free tier holds ~${FREE_TIER_STORES} stores' backups at 0 cost.`)
console.log(
  `- First Supabase Pro invoice (₱${SUPABASE_PRO_MONTHLY.toFixed(0)}/month) is covered by ${Math.ceil(SUPABASE_PRO_MONTHLY / (PRO_EFFECTIVE - PRO_EFFECTIVE * PAYMENT_FEE_RATE))} paying stores.`,
)
console.log(
  '- Every store covers its own variable cost from the first one, so the server bill never decides whether the business works — the number of stores does.',
)

console.log('\n## What the subscription alone buys a full-time team\n')
for (const scenario of SCENARIOS) {
  const rows = rowsByScenario.get(scenario.id)
  const last = rows[MONTHS - 1]
  console.log(
    `- ${scenario.label}: ${money(last.subscription)}/month of subscription at M24 — ${last.subscription >= 60000 ? 'enough to fund a small team' : 'not a salary, which is why institutional licences are the revenue line rather than a later add-on'}.`,
  )
}

console.log(`\nWrote revenue-projection.csv (${csvLines.length - 1} rows).`)
